const fn = new Function(code + "\nreturn { createDisclosure };");
const { createDisclosure } = fn();
const d = createDisclosure();
if (d.isOpen()) throw new Error("Starts closed.");
if (d.toggle() !== "expanded") throw new Error("First toggle returns 'expanded'.");
if (!d.isOpen()) throw new Error("Now open.");
if (d.toggle() !== "collapsed") throw new Error("Second toggle returns 'collapsed'.");

const fn = new Function(code + "\nreturn { createDisclosure };");
const { createDisclosure } = fn();
const d = createDisclosure();
let s = d.state();
if (s.ariaExpanded !== "false" || s.hidden !== true) throw new Error("Closed: aria-expanded 'false', hidden true.");
d.toggle();
s = d.state();
if (s.ariaExpanded !== "true" || s.hidden !== false) throw new Error("Open: aria-expanded 'true', hidden false.");
